{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Esaxerenone, a close analogue sharing the methylsulfonylphenyl and heteroaromatic core, had absolute oral bioavailability of 89.0% in healthy Japanese subjects in the fasting state, directly supporting high F for the query under fasted conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Basmisanil, a structurally related heteroaromatic drug, showed approximately 75% absolute oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Imatinib, which shares the methylpyridine/heteroaryl motif, had absolute bioavailability of 97.2% compared with IV infusion in patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Odanacatib, containing a methylsulfonylphenyl group like the query, had 30% absolute bioavailability in the fasted state at its 50 mg dose, still above the 20% threshold and supportive of high F; lower F was attributed to solubility-limited absorption at high dose.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "BI 425809, a methylsulfonylphenyl-containing analogue, had 71.64% absolute bioavailability as a fasted 25 mg tablet in healthy participants, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Bitopertin, another methylsulfonylphenyl amide analogue, was judged to have high absolute bioavailability based on minimal CYP3A4 inhibition effects, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer analogues with direct human absolute bioavailability measurements in fasted conditions report F values from approximately 30% to 98%, all above the 20% threshold. The closest structural analogues share the methylsulfonylphenyl/heteroaryl pharmacophore and consistently support high oral bioavailability. No affirmative evidence for F < 20% was found.",
  "evidence_gaps": [
    "No direct experimental absolute bioavailability measurement exists for the exact query molecule; prediction relies on close analogues.",
    "Dose-dependent solubility-limited absorption observed for odanacatib at 50 mg could be relevant if the query is dosed very high, but no such data are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

